sys_script_client.script:
// Flag global para impedir um loop infinito
var g_form_submit_processed_h13 = false;

function onSubmit() {

    // 1. Se este for o *segundo* envio (disparado pelo nosso callback), permita
    if (g_form_submit_processed_h13) {
        return true;
    }

    // 2. Só rodar se for um registo novo
    if (!g_form.isNewRecord()) {
        return true; // Se estiver a editar, permitir
    }

    // 3. Só rodar se o estado for 'Aprovado' (H13)
    // var ESTADO_APROVADO = '3' || '1';
    // if (g_form.getValue('state') != ESTADO_APROVADO) {
    //     return true; // Se não for 'Aprovado', permitir
    // }

	var ESTADO_APROVADO = ['3', '1'];
	if (!ESTADO_APROVADO.includes(g_form.getValue('state'))) {
    	  return true;
		}


    // 4. Chamar o GlideAjax (ASSÍNCRONO)
    var baseId = g_form.getValue('base');

    var ga = new GlideAjax('x_1836079_office.BaseUtils'); // O seu Script Include
    ga.addParam('sysparm_name', 'checkBaseOccupancy'); // A nossa função da H13
    ga.addParam('sysparm_base_id', baseId);

    // Use getXML() (assíncrono) e diga-lhe qual função chamar quando a resposta voltar
    ga.getXML(h13ValidationCallback);

    // 5. PARE o envio do formulário (pela primeira vez)
    // O nosso callback (h13ValidationCallback) irá reenviá-lo se a validação passar.
    return false;
}

// 6. O "Callback" (Função chamada quando o servidor responder)
function h13ValidationCallback(response) {

    // Pega a resposta (o JSON) do Script Include
    var jsonResponse = response.responseXML.documentElement.getAttribute("answer");

    // Verifica se a resposta não é nula (caso o Script Include ainda tenha erros)
    if (!jsonResponse) {
        g_form.addErrorMessage('Erro de Validação: O servidor não respondeu. Contacte o Admin.');
        return; // Para
    }

    var responseObj = JSON.parse(jsonResponse);

    // 7. A Lógica de Validação
    if (responseObj.current >= responseObj.max) {
        // FALHOU: A base está lotada
        g_form.addErrorMessage("Validation Failed : The base '" +
            g_form.getDisplayValue('base.name') +
            "'has already reached maximum capacity (" + responseObj.current + "/" + responseObj.max + ").");

        // Não fazer nada (o envio já foi parado)

    } else {
        // SUCESSO: A base tem vagas

        // 1. Define a nossa flag global como 'true'
        g_form_submit_processed_h13 = true;

        // 2. Reenvia o formulário. O script 'onSubmit' irá rodar de novo,
        // mas desta vez a flag (passo 1) irá deixá-lo passar.
        g_form.submit(g_form.getActionName());
    }
}
